class Dispatcher {
public:
    int Dispatch(void* headerBuffer) {
        Header* header = (Header*)headerBuffer;
        if (header == nullptr) return -1;
        switch (header->type) {
        case 1:
            store.Save(header->size);
            break;
        case 2:
        case 3:
            store.Save(1);
            break;
        case 4:
            store.Save(4);
        default:
            store.Reject();
            return -2;
        }
        return 0;
    }
private:
    PacketStore store;
};

