namespace SyntheticOrders;
public interface IOrderStore { void Save(int amount); }
public class OrderStore : IOrderStore {
    private int total;
    public void Save(int amount) { total = amount; }
    public int ReadTotal() { return total; }
}
public class Validator { public bool Accept(int amount) { return amount > 0; } }
public class OrderService {
    private OrderStore store = new OrderStore();
    private Validator validator = new Validator();
    public bool Submit(int amount) {
        if (!validator.Accept(amount)) return false;
        store.Save(amount);
        return true;
    }
    private void Unrelated() { }
}
public class OrderController {
    private OrderService service = new OrderService();
    public bool Submit(int amount) { return service.Submit(amount); }
}
public class UnrelatedReport { public void Print() { } }
